vals = {'P':100,'N':320,'B':330,'R':500,'Q':900,'K':0}
central = {"d4","e4","d5","e5"}

def evaluate(pos):
    if pos.get("game_over"):
        w = pos.get("winner")
        if w == "white": return 100000
        if w == "black": return -100000
        return 0
    f = pos["fen"].split()
    placement = f[0]
    sc = 0
    for r, row in enumerate(placement.split("/")):
        rank = 8 - r
        file_i = 0
        for ch in row:
            if ch.isdigit():
                file_i += int(ch)
            else:
                sq = "abcdefgh"[file_i] + str(rank)
                v = vals[ch.upper()]
                if ch.isupper():
                    sc += v
                    if sq in central: sc += 12
                else:
                    sc -= v
                    if sq in central: sc -= 12
                file_i += 1
    # check: side to move in check
    if pos.get("in_check"):
        sc += 25 if f[1] == "b" else -25
    return sc

